package O1;
import java.nio.file.*;
public class PatchUpdaterTest {
 static int checks;static final String URL="https://github.com/"+DeliveryPolicy.REPO+"/releases/download/beta-apk-v204/FFBE-v204.apk",SHA="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);checks++;}
 static byte[] pointer(String channel,String pkg,long version,String enabled,String url,String sha,long size)throws Exception{return ("{\"channel\":\""+channel+"\",\"package\":\""+pkg+"\",\"versionCode\":"+version+(enabled==null?"":",\"apk_update_enabled\":"+enabled)+",\"apk_url\":\""+url+"\",\"sha256\":\""+sha+"\",\"bytes\":"+size+"}").getBytes("UTF-8");}
 public static void main(String[] args)throws Exception {
  Path stage=Paths.get(args[0]);byte[] root=Files.readAllBytes(stage.resolve("payload/root_delivery.tsv")),content=Files.readAllBytes(stage.resolve("payload/content_delivery.tsv")),release=Files.readAllBytes(stage.resolve("payload/delivery_release.tsv"));DeliveryPolicy.Config c=new DeliveryPolicy.Config(release,root,content);
  Path actual=stage.resolve("asset_publication/patch_version.json");check(PatchUpdater.notificationURL(Files.readAllBytes(actual),c)==null,"actual frozen version-202 disabled beta pointer never announces unpublished 203 APK");
  check(PatchUpdater.notificationURL(pointer("beta",DeliveryPolicy.PACKAGE,204,"false",URL,SHA,10),c)==null,"explicit disabled pointer suppresses even higher APK");
  check(PatchUpdater.notificationURL(pointer("beta",DeliveryPolicy.PACKAGE,203,"true",URL,SHA,10),c)==null,"equal installed APK never notifies");check(PatchUpdater.notificationURL(pointer("beta",DeliveryPolicy.PACKAGE,202,"true",URL,SHA,10),c)==null,"older APK never notifies");
  check(PatchUpdater.notificationURL(pointer("prod",DeliveryPolicy.PACKAGE,204,"true",URL,SHA,10),c)==null,"cross-channel APK notification rejected");check(PatchUpdater.notificationURL(pointer("beta","com.other.package",204,"true",URL,SHA,10),c)==null,"wrong package notification rejected");
  check(URL.equals(PatchUpdater.notificationURL(pointer("beta",DeliveryPolicy.PACKAGE,204,"true",URL,SHA,10),c)),"newer enabled compatible APK returns user-selectable download link");check(URL.equals(PatchUpdater.notificationURL(pointer("beta",DeliveryPolicy.PACKAGE,204,null,URL,SHA,10),c)),"omitted enable flag permits compatible newer notification");
  check(PatchUpdater.notificationURL(pointer("beta",DeliveryPolicy.PACKAGE,204,"true",URL,"invalid",10),c)==null,"invalid advertised SHA suppresses notification");check(PatchUpdater.notificationURL(pointer("beta",DeliveryPolicy.PACKAGE,204,"true",URL,SHA,0),c)==null,"invalid advertised size suppresses notification");
  check(PatchUpdater.notificationURL(pointer("beta",DeliveryPolicy.PACKAGE,204,"true",URL.replace(DeliveryPolicy.REPO,"other/repo"),SHA,10),c)==null,"foreign repository download rejected");check(PatchUpdater.notificationURL(pointer("beta",DeliveryPolicy.PACKAGE,204,"true","https://github.com/"+DeliveryPolicy.REPO+"/releases/latest/download/FFBE.apk",SHA,10),c)==null,"mutable latest download rejected");
  check(PatchUpdater.notificationURL(pointer("beta",DeliveryPolicy.PACKAGE,204,"\"false\"",URL,SHA,10),c)==null,"mistyped enable flag fails closed");
  String prodURL=URL.replace("beta-apk-v204","patch-204");check(PatchUpdater.notificationURL(pointer("beta",DeliveryPolicy.PACKAGE,204,"true",prodURL,SHA,10),c)==null,"beta updater never presents a production-tag APK");
  String prodRelease=new String(release,"UTF-8").replace("\nbeta\t","\nprod\t").replace(DeliveryPolicy.metadataURL("beta","patch_version.json"),DeliveryPolicy.metadataURL("prod","patch_version.json")).replace(DeliveryPolicy.metadataURL("beta","manifest.json"),DeliveryPolicy.metadataURL("prod","manifest.json"));DeliveryPolicy.Config prod=new DeliveryPolicy.Config(prodRelease.getBytes("UTF-8"),root,content);
  check(PatchUpdater.notificationURL(pointer("prod",DeliveryPolicy.PACKAGE,204,"true",URL,SHA,10),prod)==null,"production updater never presents a beta-tag APK");check(PatchUpdater.notificationURL(pointer("prod",DeliveryPolicy.PACKAGE,204,"true","https://ffbe.luminest.io/downloads/beta/releases/FFBE-v204.apk",SHA,10),prod)==null,"production updater rejects beta origin path");check(prodURL.equals(PatchUpdater.notificationURL(pointer("prod",DeliveryPolicy.PACKAGE,204,"true",prodURL,SHA,10),prod)),"production channel accepts a matching non-beta immutable release");
  System.out.println("PASSED "+checks+" actual APK notification/no-notification decisions; no UI, download or install invoked");
 }
}
